import { OrderNotFoundError, PaymentDeclinedError, ValidationError } from "./errors.js";
import { orderCancelled, orderPlaced } from "./events.js";
import { cancel, createOrder, totalCents, type NewOrder, type Order } from "./order.js";
import type {
  Clock,
  CustomerOrdersQuery,
  EventPublisher,
  IdGenerator,
  OrderCursor,
  OrderRepository,
  PaymentGateway,
} from "./ports.js";

export const MAX_LIST_LIMIT = 100;

export interface OrderPage {
  readonly orders: Order[];
  /** Present when more orders exist after this page. */
  readonly next?: OrderCursor;
}

export interface OrderServiceDeps {
  readonly orders: OrderRepository;
  readonly events: EventPublisher;
  readonly payments: PaymentGateway;
  readonly clock: Clock;
  readonly ids: IdGenerator;
}

export interface CancelOrderOptions {
  readonly reason?: string;
}

/**
 * Application service: orchestrates the order use cases over the ports.
 * It owns the order of side effects: authorize, persist, then publish.
 */
export class OrderService {
  constructor(private readonly deps: OrderServiceDeps) {}

  async placeOrder(command: NewOrder): Promise<Order> {
    const { orders, events, payments, clock, ids } = this.deps;

    const order = createOrder(command, {
      id: ids.nextId(),
      placedAt: clock.now().toISOString(),
    });

    const authorization = await payments.authorize({
      orderId: order.id,
      customerId: order.customerId,
      amountMinor: totalCents(order),
      currency: order.currency,
    });
    if (!authorization.authorized) {
      throw new PaymentDeclinedError(order.id, authorization.declineReason ?? "declined by provider");
    }

    await orders.save(order);
    await events.publish(orderPlaced(order));
    return order;
  }

  async getOrder(id: string): Promise<Order> {
    const order = await this.deps.orders.findById(id);
    if (order === undefined) {
      throw new OrderNotFoundError(id);
    }
    return order;
  }

  /** Lists one customer's orders, newest first, one page at a time. */
  async listOrders(query: CustomerOrdersQuery): Promise<OrderPage> {
    if (query.customerId.trim() === "") {
      throw new ValidationError([{ path: "customerId", message: "is required" }]);
    }
    if (!Number.isInteger(query.limit) || query.limit < 1 || query.limit > MAX_LIST_LIMIT) {
      throw new ValidationError([{ path: "limit", message: `must be an integer between 1 and ${MAX_LIST_LIMIT}` }]);
    }
    // Ask for one extra row to learn whether another page exists.
    const rows = await this.deps.orders.findByCustomer({ ...query, limit: query.limit + 1 });
    const orders = rows.slice(0, query.limit);
    const last = orders.at(-1);
    return rows.length > query.limit && last !== undefined
      ? { orders, next: { placedAt: last.placedAt, id: last.id } }
      : { orders };
  }

  async cancelOrder(id: string, options: CancelOrderOptions = {}): Promise<Order> {
    const { orders, events, clock } = this.deps;

    const existing = await this.getOrder(id);
    const cancelledAt = clock.now().toISOString();
    const cancelled = cancel(existing, cancelledAt);

    await orders.save(cancelled);
    await events.publish(orderCancelled(cancelled, cancelledAt, options.reason));
    return cancelled;
  }
}
import type { OrderService } from "../core/orderService.js";
import { toErrorResponse } from "./errorMapper.js";
import { errorResponse, json, queryOf, splitPath, type HttpRequest, type HttpResponse } from "./http.js";
import { parseCancelRequest, parseListOrdersQuery, parsePlaceOrderRequest } from "./requestParsing.js";
import { toOrderListResponse, toOrderResponse } from "./responses.js";

export interface OrdersController {
  handle(request: HttpRequest): Promise<HttpResponse>;
}

type RouteMatch =
  | { readonly kind: "placeOrder" }
  | { readonly kind: "health" }
  | { readonly kind: "listOrders" }
  | { readonly kind: "getOrder"; readonly id: string }
  | { readonly kind: "cancelOrder"; readonly id: string }
  | { readonly kind: "methodNotAllowed"; readonly allow: string }
  | { readonly kind: "notFound" };

/**
 * REST handlers for orders-api:
 *   POST /orders               place an order           -> 201
 *   GET  /orders?customerId=   list a customer's orders -> 200 { orders: [...] }
 *   GET  /orders/{id}          read an order            -> 200
 *   POST /orders/{id}/cancel   cancel a placed order    -> 200
 *   GET  /health               liveness probe           -> 200 { status: "ok" }
 * Handlers are pure functions of `{ method, path, body }` plus the order service.
 */
export function createOrdersController(service: OrderService): OrdersController {
  return {
    async handle(request: HttpRequest): Promise<HttpResponse> {
      try {
        return await dispatch(service, request);
      } catch (error) {
        return toErrorResponse(error);
      }
    },
  };
}

async function dispatch(service: OrderService, request: HttpRequest): Promise<HttpResponse> {
  const route = matchRoute(request.method, request.path);
  switch (route.kind) {
    case "placeOrder": {
      const order = await service.placeOrder(parsePlaceOrderRequest(request.body));
      return json(201, toOrderResponse(order));
    }
    case "listOrders": {
      const page = await service.listOrders(parseListOrdersQuery(queryOf(request.path)));
      return json(200, toOrderListResponse(page));
    }
    case "health":
      return json(200, { status: "ok" });
    case "getOrder": {
      const order = await service.getOrder(route.id);
      return json(200, toOrderResponse(order));
    }
    case "cancelOrder": {
      const { reason } = parseCancelRequest(request.body);
      const order = await service.cancelOrder(route.id, reason === undefined ? {} : { reason });
      return json(200, toOrderResponse(order));
    }
    case "methodNotAllowed":
      return errorResponse(405, "method_not_allowed", `Allowed: ${route.allow}`);
    case "notFound":
      return errorResponse(404, "route_not_found", `No route for ${request.method} ${request.path}`);
  }
}

function matchRoute(method: string, path: string): RouteMatch {
  const verb = method.toUpperCase();
  const segments = splitPath(path);
  const [root, id, action] = segments;
  if (root === "health" && segments.length === 1) {
    return verb === "GET" ? { kind: "health" } : { kind: "methodNotAllowed", allow: "GET" };
  }
  if (root !== "orders" || segments.length > 3) {
    return { kind: "notFound" };
  }
  if (id === undefined) {
    if (verb === "POST") {
      return { kind: "placeOrder" };
    }
    return verb === "GET" ? { kind: "listOrders" } : { kind: "methodNotAllowed", allow: "GET, POST" };
  }
  const orderId = decodeSegment(id);
  if (action === undefined) {
    return verb === "GET" ? { kind: "getOrder", id: orderId } : { kind: "methodNotAllowed", allow: "GET" };
  }
  if (action === "cancel") {
    return verb === "POST" ? { kind: "cancelOrder", id: orderId } : { kind: "methodNotAllowed", allow: "POST" };
  }
  return { kind: "notFound" };
}

function decodeSegment(segment: string): string {
  try {
    return decodeURIComponent(segment);
  } catch {
    return segment;
  }
}
import type { DomainEvent } from "./events.js";
import type { Order, OrderStatus } from "./order.js";

/** Position in the newest-first ordering of one customer's orders. */
export interface OrderCursor {
  readonly placedAt: string;
  readonly id: string;
}

export interface CustomerOrdersQuery {
  readonly customerId: string;
  readonly status?: OrderStatus;
  readonly limit: number;
  /** Return only orders strictly older than this position. */
  readonly after?: OrderCursor;
}

/** Persistence of orders. Implementations must return copies, never shared mutable state. */
export interface OrderRepository {
  save(order: Order): Promise<void>;
  findById(id: string): Promise<Order | undefined>;
  /** Orders of one customer, newest first (by `placedAt`, then id), at most `limit`, starting after `after`. */
  findByCustomer(query: CustomerOrdersQuery): Promise<Order[]>;
}

/** Publishes domain events to the event bus. Resolves once the bus has accepted the event. */
export interface EventPublisher {
  publish(event: DomainEvent): Promise<void>;
}

export interface PaymentAuthorizationRequest {
  readonly orderId: string;
  readonly customerId: string;
  readonly amountMinor: number;
  readonly currency: string;
}

export interface PaymentAuthorization {
  readonly authorized: boolean;
  /** Provider reference, present when authorized. */
  readonly reference?: string;
  /** Provider reason, present when declined. */
  readonly declineReason?: string;
}

/**
 * Asks the payment provider to authorize an amount.
 * Implementations throw `PaymentUnavailableError` when the provider cannot be reached;
 * a refusal is a normal result (`authorized: false`), not an error.
 */
export interface PaymentGateway {
  authorize(request: PaymentAuthorizationRequest): Promise<PaymentAuthorization>;
}

export interface Clock {
  now(): Date;
}

export interface IdGenerator {
  nextId(): string;
}
